"""Audit the stopped nine-JVM timing prefix without computing performance ratios.

The prepared complete-study analyzer remains unchanged. This audit reuses only
its independent raw schema/route checks. No experimental runner, runs.json, or
summary.json is imported or read; no latency or allocation ratio is computed.
"""
import argparse
from collections import Counter
import importlib.util
import json
from pathlib import Path
import traceback

HERE = Path(__file__).resolve().parent
FULL_ANALYZER = HERE / 'analyze-timing-independent.py'
FULL_ANALYZER_SHA = 'd1db1bf0e8c714471d15dc8d66acd2490214c6857fb606f3b3e95504fc34d423'
spec = importlib.util.spec_from_file_location('prepared_independent_raw_schema', FULL_ANALYZER)
raw = importlib.util.module_from_spec(spec)
spec.loader.exec_module(raw)


def differences(left, right, prefix=''):
    result = []
    if isinstance(left, dict) and isinstance(right, dict):
        for key in sorted(left.keys() | right.keys()):
            name = prefix + '.' + key if prefix else key
            if key not in left or key not in right:
                result.append({'field': name, 'all': left.get(key), 'omit': right.get(key)})
            else:
                result += differences(left[key], right[key], name)
    elif left != right:
        result.append({'field': prefix, 'all': left, 'omit': right})
    return result


def runtime_preservation(preflight):
    import hashlib
    results = []
    for expected in preflight['runtimeManifest']:
        path = Path(expected['path'])
        if expected['kind'] == 'file':
            actual = raw.digest(path)
            count = None
        else:
            require_files = []
            for item in sorted(path.rglob('*')):
                raw.require(not item.is_symlink(), 'Unexpected runtime symlink')
                if item.is_file():
                    require_files.append(item)
            h = hashlib.sha256()
            for item in require_files:
                h.update(item.relative_to(path).as_posix().encode() + b'\0')
                h.update(bytes.fromhex(raw.digest(item)))
            actual, count = h.hexdigest(), len(require_files)
            raw.require(count == expected['files'], 'Runtime tree file count changed')
        raw.require(actual == expected['sha256'], 'Runtime artifact changed: ' + str(path))
        results.append({'path': str(path), 'kind': expected['kind'], 'sha256': actual,
                        'files': count, 'unchanged': True})
    watched = {}
    for path, expected in preflight['watchedFiles'].items():
        actual = raw.digest(path)
        raw.require(actual == expected, 'Frozen source/protocol/evidence file changed: ' + path)
        watched[path] = actual
    return {'allRuntimeEntriesUnchanged': True, 'runtimeEntries': results,
        'allWatchedFilesUnchanged': True, 'watchedFiles': watched}


def audit(protocol_path, comparison):
    raw.require(raw.digest(FULL_ANALYZER) == FULL_ANALYZER_SHA, 'Prepared full-study analyzer changed')
    protocol = raw.read_json(protocol_path)
    raw.require(raw.digest(protocol_path) == raw.EXPECTED_PROTOCOL_SHA, 'Frozen protocol changed')
    raw.require(raw.text(comparison / 'used-protocol.json') == Path(protocol_path).read_text(), 'Consumed protocol differs')
    raw.require(protocol['arms'] == raw.ARMS and protocol['balancedOrders'] == raw.ORDERS
        and protocol['fixtureOrdersByRound'] == raw.FIXTURE_ORDERS and protocol['configuration'] == raw.CONFIG
        and protocol['warmup'] == 8 and protocol['iterations'] == 5, 'Frozen design changed')
    runtime = raw.read_json(protocol['runtimeDescriptorFile'])
    raw.require(runtime == protocol['runtime'] and raw.digest(protocol['runtimeDescriptorFile'])
        == protocol['runtimeDescriptorFileSha256'], 'Runtime descriptor changed')
    cp = raw.text(runtime['classpathFile']).strip()
    raw.require(raw.digest(runtime['classpathFile']) == runtime['classpathFileSha256'], 'Classpath text changed')
    schedule = []
    for round_index, order in enumerate(raw.ORDERS):
        for fixture_position, fixture in enumerate(raw.FIXTURE_ORDERS[round_index]):
            for arm_position, arm in enumerate(order):
                name = f'round-{round_index:02d}-{fixture_position:02d}-{fixture}-{arm_position:02d}-{arm}'
                schedule.append((name, fixture, arm, round_index, fixture_position, arm_position))
    folders = {p.name for p in comparison.glob('round-*') if p.is_dir()}
    raw.require(folders == {item[0] for item in schedule[:9]}, 'Observed run set is not precisely the first nine frozen forks')
    runs, metadata_reference, route_reference = [], {}, {}
    last_end = 0
    for name, fixture, arm, round_index, fixture_position, arm_position in schedule[:9]:
        folder = comparison / name
        run = raw.read_fork(folder, fixture, arm, round_index, fixture_position, arm_position, protocol, cp)
        raw.require(run['process']['startedEpochNs'] >= last_end, 'Recorded JVM intervals overlap')
        last_end = run['process']['finishedEpochNs']
        metadata = raw.normalized(run['metadata'])
        if fixture not in metadata_reference:
            metadata_reference[fixture], route_reference[fixture] = metadata, run['measuredRouteHistogram']
        raw.require(metadata == metadata_reference[fixture]
            and run['measuredRouteHistogram'] == route_reference[fixture], 'Input/JVM/measured-route mismatch')
        for extra in ('console.log', 'validation.json'):
            path = folder / extra
            raw.SOURCE_FILES[str(path)] = raw.digest(path)
        # Preserve all raw query records, but do not publish timing estimates for
        # this incomplete study. read_fork's median fields are deliberately dropped.
        run.pop('measurementMedians')
        run.pop('coldFirstQuery')
        runs.append(run)
    pairs, unpaired = [], []
    indexed = {(r['fixture'], r['round'], r['arm']): r for r in runs}
    for fixture in raw.FIXTURES:
        for round_index in range(6):
            all_key, omit_key = (fixture, round_index, 'dense-all'), (fixture, round_index, 'dense-omit')
            if all_key not in indexed or omit_key not in indexed:
                if all_key in indexed or omit_key in indexed:
                    unpaired.append({'fixture': fixture, 'round': round_index})
                continue
            for a, b in zip(indexed[all_key]['samples'], indexed[omit_key]['samples'], strict=True):
                raw.require(a['iteration'] == b['iteration'] and a['stage'] == b['stage'], 'Paired chronology differs')
                pair = {'fixture': fixture, 'round': round_index, 'iteration': a['iteration'], 'stage': a['stage'],
                    'allResolverCalls': a['counters']['lazyValueCalls'], 'omitResolverCalls': b['counters']['lazyValueCalls'],
                    'counterDifferences': differences(a['counters'], b['counters']),
                    'routeDifferences': differences(raw.route(a), raw.route(b)),
                    'adjacencyDifferences': differences(a['adjacency'], b['adjacency']),
                    'resultDifferences': differences({k: a[k] for k in ('rows', 'bindingReads', 'checksum', 'valid',
                        'complete', 'rowCountValid', 'checksumValid', 'partialMembershipValid', 'retainedRows')},
                        {k: b[k] for k in ('rows', 'bindingReads', 'checksum', 'valid', 'complete',
                            'rowCountValid', 'checksumValid', 'partialMembershipValid', 'retainedRows')}),
                    'allLedgerPeakBytes': a['ledgerPeakBytes'], 'omitLedgerPeakBytes': b['ledgerPeakBytes']}
                pair['passedExactCounterRouteAndResultMatch'] = not any(pair[key] for key in (
                    'counterDifferences', 'routeDifferences', 'adjacencyDifferences', 'resultDifferences'))
                pairs.append(pair)
    raw.require(len(pairs) == 39 and not unpaired, 'Unexpected number of completed DENSE pairs')
    mismatches = [p for p in pairs if not p['passedExactCounterRouteAndResultMatch']]
    per_arm = []
    for fixture in raw.FIXTURES:
        for arm in raw.ARMS:
            matching = [r for r in runs if r['fixture'] == fixture and r['arm'] == arm]
            if not matching:
                continue
            values = [s for r in matching for s in r['samples']]
            counts = Counter(s['counters']['lazyValueCalls'] for s in values)
            per_arm.append({'fixture': fixture, 'arm': arm, 'forks': len(matching), 'queries': len(values),
                'resolverCallFrequencies': {str(key): count for key, count in sorted(counts.items())},
                'ledgerPeakValues': sorted({s['ledgerPeakBytes'] for s in values}),
                'adjacencyLookupHits': sorted({s['adjacency']['lookupHits'] for s in values})})
    preflight = raw.read_json(comparison / 'preflight.json')
    post = raw.read_json(comparison / 'post-run-preservation.json')
    raw.require(post == {'identityFilesUnchanged': True, 'runtimeIdentityUnchanged': True},
                'Runner post-preservation receipt did not pass')
    preserved = runtime_preservation(preflight)
    raw.require(all(raw.digest(path) == expected for path, expected in raw.SOURCE_FILES.items()),
                'Raw file changed during independent audit')
    return {'format': 1, 'validPartialAudit': True, 'completeStudy': False,
        'acceptedPerformanceComparisons': False, 'performanceRatiosComputed': False,
        'protocolSha256': raw.EXPECTED_PROTOCOL_SHA, 'auditScriptSha256': raw.digest(__file__),
        'preparedAnalyzerFile': str(FULL_ANALYZER), 'preparedAnalyzerSha256': FULL_ANALYZER_SHA,
        'plannedJvms': 36, 'completedJvms': 9, 'queries': sum(len(r['samples']) for r in runs),
        'warmupQueries': sum(s['stage'] == 'warmup' for r in runs for s in r['samples']),
        'measuredQueries': sum(s['stage'] == 'measurement' for r in runs for s in r['samples']),
        'completedDenseQueryPairs': len(pairs), 'matchingDenseQueryPairs': len(pairs) - len(mismatches),
        'mismatches': mismatches, 'allDensePairChecks': pairs, 'perArmCounterObservations': per_arm,
        'allResultOraclesPassed': True, 'allQueryLedgerEndpointsZero': True, 'allActualRouteChecksPassed': True,
        'serialIntervals': True, 'allNineProcessesExitedZero': True,
        'postPreservationReceipt': post, 'independentPreservation': preserved,
        'rawInputs': dict(raw.SOURCE_FILES), 'runs': runs,
        'interpretation': 'The frozen protocol is incomplete and failed its exact DENSE matching prerequisite. No replacements, excluded warmups, relaxed gate, or accepted performance ratios are supplied. Raw timing/allocation records remain preserved without comparison estimates.',
        'causeLimit': 'The timed harness records lazyValueCalls but has no per-target weak/witness miss counters. A one-call mismatch does not identify its cache cause or establish an ownership defect.'}


def write_report(data):
    lines = ['# Independent audit of the stopped timing study', '',
        '**The frozen performance study is incomplete and has no accepted performance comparison.** '
        'Its first nine scheduled JVMs completed, then the exact DENSE resolver-matching prerequisite failed. '
        'This audit preserves the failure and does not compute latency or allocation ratios.', '',
        f"The independent audit validated **{data['completedJvms']} JVMs**, **{data['queries']} queries** "
        + f"({data['warmupQueries']} warmups and {data['measuredQueries']} measurements). "
        + f"Of **{data['completedDenseQueryPairs']}** completed DENSE query pairs, "
        + f"**{data['matchingDenseQueryPairs']}** match every recorded counter, route, adjacency, and result observation.", '',
        '## Exact mismatches', '',
        '| Fixture | Zero-based round | Stage | Iteration | All-enabled resolver calls | Omitted resolver calls | Counter difference |',
        '|---|---:|---|---:|---:|---:|---|']
    for item in data['mismatches']:
        differences_text = '; '.join(f"{d['field']}: {d['all']} → {d['omit']}" for d in item['counterDifferences'])
        lines.append(f"| {item['fixture']} | {item['round']} | {item['stage']} | {item['iteration']} | "
            + f"{item['allResolverCalls']:,} | {item['omitResolverCalls']:,} | {differences_text} |")
    lines += ['', 'The JSON receipt lists every completed pair and recursively compares the complete counter dictionaries. '
        'Route/tier, adjacency, and result differences are recorded separately. Ledger peaks differ between publication arms as expected, so they are reported as arm observations rather than counter-equality failures.', '',
        '## All observed resolver and ledger values', '',
        '| Fixture | Arm | Queries | Resolver-call frequencies | Ledger peaks, bytes |',
        '|---|---|---:|---|---|']
    for item in data['perArmCounterObservations']:
        frequencies = ', '.join(f'{int(value):,}: {count} queries' for value, count in item['resolverCallFrequencies'].items())
        peaks = ', '.join(f'{value:,}' for value in item['ledgerPeakValues'])
        lines.append(f"| {item['fixture']} | {item['arm']} | {item['queries']} | {frequencies} | {peaks} |")
    lines += ['', '## Result, execution, and preservation checks', '',
        'Every query retains the prescribed count/checksum, full-consumption flags, and zero ledger endpoints; shared-tail also records a valid exact-bag oracle. Every measured query uses compiled native IR through normal AUTO. All query-time adjacency checks and outer-root audits pass. All nine Java processes exited successfully, and their recorded intervals are serial and nonoverlapping. The observed directories are exactly the first nine entries of the frozen schedule.', '',
        'The runner\'s post-preservation receipt reports unchanged identities. This audit additionally rehashed all '
        + str(len(data['independentPreservation']['runtimeEntries'])) + ' runtime classpath entries and all '
        + str(len(data['independentPreservation']['watchedFiles'])) + ' watched source/protocol/evidence files, reproducing their preserved identities. '
        'Raw command, process, sample, root-audit, console, validation, and preservation files are pinned by hash. The prepared complete-study analyzer remains unchanged.', '',
        '## What the failure establishes', '',
        'The observed exception is a resolver-work equality failure under the prospectively frozen gate. It is not a result failure, process failure, route change, or nonzero-ledger failure. The timed harness has no per-target weak-reference or witness-miss telemetry, so these records alone cannot identify why the extra lazy-value call occurred.', '',
        'The failed warmup remains part of the protocol. The successful measured queries do not override a gate that applied to every query, and the nine-fork prefix is not substituted for the planned thirty-six-fork comparison. A separate diagnostic investigation may examine the counter variation while keeping this original study failed and incomplete.', '',
        f"Frozen protocol SHA-256: `{data['protocolSha256']}`.", '',
        f"Partial audit script SHA-256: `{data['auditScriptSha256']}`.", '']
    return '\n'.join(lines)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--protocol', type=Path, required=True)
    parser.add_argument('--comparison', type=Path, required=True)
    parser.add_argument('--output', type=Path, required=True)
    parser.add_argument('--analysis-slot-released', action='store_true')
    args = parser.parse_args()
    raw.require(args.analysis_slot_released, 'Coordinator analysis slot release required')
    output = args.output.resolve()
    output.mkdir(parents=True, exist_ok=False)
    try:
        data = audit(args.protocol.resolve(strict=True), args.comparison.resolve(strict=True))
        (output / 'independent-partial-audit.json').write_text(json.dumps(data, indent=2, sort_keys=True) + '\n')
        (output / 'independent-partial-report.md').write_text(write_report(data))
        print(json.dumps({'validPartialAudit': True, 'completedJvms': data['completedJvms'], 'queries': data['queries'],
            'warmups': data['warmupQueries'], 'measurements': data['measuredQueries'],
            'mismatches': data['mismatches'], 'acceptedPerformanceComparisons': False, 'output': str(output)}))
    except BaseException as error:
        (output / 'audit-failure.json').write_text(json.dumps({'exception': type(error).__name__, 'message': str(error),
            'traceback': traceback.format_exc(), 'acceptedPerformanceComparisons': False,
            'sourceFilesRead': raw.SOURCE_FILES}, indent=2) + '\n')
        raise


if __name__ == '__main__':
    main()
